CREATE SCHEMA input_first;
CREATE SCHEMA input_second;
CREATE TABLE input_target_audit(value integer);
CREATE FUNCTION input_first.retained_target(value integer) RETURNS integer LANGUAGE sql VOLATILE AS 'INSERT INTO public.input_target_audit VALUES ($1+10); SELECT $1+10';
CREATE FUNCTION input_second.retained_target(value integer) RETURNS integer LANGUAGE sql VOLATILE AS 'INSERT INTO public.input_target_audit VALUES ($1+100); SELECT $1+100';
CREATE FUNCTION input_first.retained_target_rows(value integer) RETURNS TABLE(result integer) LANGUAGE sql VOLATILE AS 'INSERT INTO public.input_target_audit VALUES ($1+10); SELECT $1+10';
CREATE FUNCTION input_second.retained_target_rows(value integer) RETURNS TABLE(result integer) LANGUAGE sql VOLATILE AS 'INSERT INTO public.input_target_audit VALUES ($1+100); SELECT $1+100';
SET search_path=input_first,public;
SELECT retained_target((set_config('search_path','input_second,public',false) IS NOT NULL)::integer);
SELECT value FROM public.input_target_audit ORDER BY value;
TRUNCATE public.input_target_audit;
SET search_path=input_first,public;
SELECT retained_target(1+retained_target((set_config('search_path','input_second,public',false) IS NOT NULL)::integer));
SELECT value FROM public.input_target_audit ORDER BY value;
TRUNCATE public.input_target_audit;
SET search_path=input_first,public;
SELECT result FROM retained_target_rows((set_config('search_path','input_second,public',false) IS NOT NULL)::integer);
SELECT value FROM public.input_target_audit ORDER BY value;
RESET search_path;
DROP FUNCTION input_second.retained_target_rows(integer);
DROP FUNCTION input_first.retained_target_rows(integer);
DROP FUNCTION input_second.retained_target(integer);
DROP FUNCTION input_first.retained_target(integer);
DROP TABLE input_target_audit;
DROP SCHEMA input_second;
DROP SCHEMA input_first;
